  class WorkflowReport { private string $workflowId; private string $reportDir; public function __construct(string $workflowId) { $this->workflowId = $workflowId; $this->reportDir = __DIR__ . '/../../../storage/reports/workflows/' . $workflowId; if (!is_dir($this->reportDir)) { mkdir($this->reportDir, 0777, true); } } public function getWorkflowId(): string { return $this->workflowId; } public function saveEventLog(array $events): void { $file = $this->reportDir . '/event_log.json'; file_put_contents($file, json_encode($events, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); } public function saveState(array $stateData): void { $file = $this->reportDir . '/workflow.json'; file_put_contents($file, json_encode($stateData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); } public function saveFinalReport(string $markdownContent): void { $file = $this->reportDir . '/final-report.md'; file_put_contents($file, $markdownContent); } public static function loadState(string $workflowId): ?array { $file = __DIR__ . '/../../../storage/reports/workflows/' . $workflowId . '/workflow.json'; if (file_exists($file)) { $data = json_decode(file_get_contents($file), true); return is_array($data) ? $data : null; } return null; } public static function listWorkflows(): array { $dir = __DIR__ . '/../../../storage/reports/workflows'; if (!is_dir($dir)) { return []; } $list = []; $folders = scandir($dir); foreach ($folders as $folder) { if ($folder === '.' || $folder === '..') continue; $file = $dir . '/' . $folder . '/workflow.json'; if (file_exists($file)) { $data = json_decode(file_get_contents($file), true); if ($data) { $list[] = $data; } } } return $list; } } 